$(document).ready(function(){$("#loginBtn").on("click",function(e){e.preventDefault(),$.ajax({type:"POST",dataType:"json",data:$("#login").serialize(),success:function(e){200==e.status?window.location.href="//"+document.domain+e.url:alert(e.msg)},error:function(e){console.log(e)}})}),$("#registerBtn").on("click",function(e){e.preventDefault(),$.ajax({type:"POST",dataType:"json",data:$("#register").serialize(),success:function(e){200==e.status?window.location.href="//"+document.domain+e.url:alert(e.msg)},error:function(e){console.log(e)}}),e.preventDefault()}),$("#forgotPassword").on("click",function(e){e.preventDefault(),$.ajax({type:"POST",dataType:"json",data:$("#forgot").serialize(),success:function(e){200==e.status?($(".beforeClick").hide(),$(".afterClick").show(),$("#statusMsg").text(e.msg),console.log(e.msg)):alert(e.msg)},error:function(e){console.log(e)}})}),$("#updatePassword").on("click",function(e){e.preventDefault(),$.ajax({type:"POST",dataType:"json",data:$("#update").serialize(),success:function(e){200==e.status?($(".beforeClick").hide(),$(".afterClick").show(),$("#statusMsg").text(e.msg)):alert(e.msg)},error:function(e){console.log(e)}})}),$.ajax({url:"https://api.apify.com/v2/datasets/58a4VXwBBF0HtxuQa/items?format=json&clean=1",success:function(e){var t=e,a=t.length,s=t[a-2],o=t[a-1],n=o.totalCases-s.totalCases,r=o.recovered-s.recovered,c=o.deaths-s.deaths;$("#confirmedCases").text(o.totalCases),$("#activeCases").text(o.activeCases),$("#recoveredCases").text(o.recovered),$("#deathCases").text(o.deaths),$("#dailyCases").text("+ "+n),$("#dailyRecovery").text("+ "+r),$("#dailyDeath").text("+ "+c)},error:function(){console.log("Error while fetching covid data")}})});